// Wind turbine showpiece, hand-made. Units: cm, real size: a 3 MW turbine, its hub 100 m up, its rotor 130 m across. Two
// more turbines stand behind it (a small wind farm). The wind blows from +Z; the nacelle turns to face it. Helpers: W.store.
const S = W.store;
S.matte = (c, r = 0.92) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: 0 });
S.white = W.paint('#f1f3f4', { metallic: 0.15, rough: 0.35 });
S.HUB = 10000; S.R = 6450;
S.beacons = [];
S.blade = (o) => { // one blade: span along +Y from y = 0, chord along X, thickness along Z, twisted along its length
  const ns = o.ns || 14, nc = o.nc || 9, span = o.span, ring = nc * 2;
  const pos = [], idx = [];
  for (let i = 0; i <= ns; i++) {
    const s = i / ns;
    const c = s < 0.06 ? o.root : s < 0.22 ? o.root + (o.max - o.root) * (s - 0.06) / 0.16 : o.max + (o.tip - o.max) * Math.pow((s - 0.22) / 0.78, 0.9);
    const th = s < 0.15 ? 0.42 - 2 * s : Math.max(0.1, 0.18 - 0.08 * s), tw = (o.twist || 0) * (1 - s) * Math.PI / 180;
    const round = s < 0.06 ? 1 : 0, y = span * s, ca = Math.cos(tw), sa = Math.sin(tw);
    for (let side = 0; side < 2; side++) for (let j = 0; j < nc; j++) {
      const u = side === 0 ? j / (nc - 1) : 1 - j / (nc - 1);
      let x, z;
      if (round) { const a = (side === 0 ? 1 : -1) * Math.PI * u; x = Math.cos(a) * c / 2; z = Math.sin(a) * c / 2; }
      else {
        const t = 5 * th * (0.2969 * Math.sqrt(u) - 0.126 * u - 0.3516 * u * u + 0.2843 * u * u * u - 0.1036 * u * u * u * u);
        x = (u - 0.35) * c; z = (0.04 * 4 * u * (1 - u) + (side === 0 ? t : -t)) * c;
      }
      pos.push(x * ca - z * sa, y, x * sa + z * ca);
    }
  }
  for (let i = 0; i < ns; i++) for (let j = 0; j < ring; j++) {
    const a = i * ring + j, b = i * ring + (j + 1) % ring, cc = (i + 1) * ring + j, d = (i + 1) * ring + (j + 1) % ring;
    idx.push(a, cc, b, b, cc, d);
  }
  const tip = ns * ring;
  for (let j = 1; j < ring - 1; j++) idx.push(tip, tip + j, tip + j + 1);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
};
W.day({ start: 15, ground: '#6f8550' });
const gr = W.group();
gr.add(W.mesh(W.box(52000, 10, 42000), S.matte('#748b52', 0.98), { at: [0, -5, -9000] }));
const dirt = S.matte('#a08c6a', 0.97);
gr.add(W.mesh(W.box(500, 6, 20000), dirt, { at: [0, 3, 9000] }), W.mesh(W.box(19000, 6, 500), dirt, { at: [-9000, 3, -15000] }), W.mesh(W.box(500, 6, 16000), dirt, { at: [0, 3, -7000] }), W.mesh(W.box(17500, 6, 500), dirt, { at: [8500, 3, -15000] }));
const trees = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), S.matte('#3f6b35', 0.95), 40);
{
  const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3();
  for (let i = 0; i < 40; i++) {
    const x = ((i * 0.618034) % 1) * 46000 - 23000, z = ((i * 0.381966 + 0.2) % 1) * 36000 - 27000;
    const far = Math.hypot(x, z) < 4000 || Math.hypot(x + 18000, z + 16000) < 3000 || Math.hypot(x - 17000, z + 20000) < 3000 ? 9000 : 0;
    const s = 280 + (i % 4) * 60;
    M.compose(P.set(x + far, s * 0.8, z), Q, Z.set(s, s * 1.2, s));
    trees.setMatrixAt(i, M);
  }
}
gr.add(trees);
W.add(gr, { label: 'పొలాలు', ground: true });

const S = W.store;
const tw = W.group();
const prof = [[0.01, 0], [230, 0], [230, 300]];
for (let i = 1; i <= 10; i++) { const k = i / 10; prof.push([230 - 95 * k, 300 + (S.HUB - 500) * k]); }
prof.push([0.01, S.HUB - 200]);
tw.add(W.mesh(W.lathe(prof, 48), S.white));
for (const y of [3300, 6600]) tw.add(W.mesh(W.torus(230 - 95 * (y - 300) / (S.HUB - 500) + 4, 8, 48, 6), W.metal('#c9cdd2'), { at: [0, y, 0], rot: [90, 0, 0] }));
tw.add(W.mesh(W.box(100, 220, 20), W.paint('#8d98a3'), { at: [0, 420, 228] }));
tw.add(W.mesh(W.box(160, 10, 60), W.metal('#9aa2aa'), { at: [0, 300, 270] }));
for (let k = 0; k < 3; k++) tw.add(W.mesh(W.box(120, 20, 60), W.metal('#9aa2aa'), { at: [0, 60 + k * 80, 300 + k * 20] }));
W.add(tw, { label: 'టవర్', heat: [28, 32] });
const fd = W.group();
fd.add(W.mesh(W.cyl(950, 1000, 120, 8), S.matte('#b9b3a7', 0.9), { at: [0, 30, 0] }));
fd.add(W.mesh(W.box(260, 200, 200), W.paint('#d9dde0'), { at: [600, 100, 500] })); // the transformer box at its foot
W.add(fd, { label: 'టవర్ పునాది', heat: [28, 55] });

const S = W.store;
// on top: the nacelle turns (yaw) to face the wind. Inside: the main shaft, the gearbox (slow → fast), the brake, the
// generator, the converter; on its roof the wind meters and a red light. Its cover lifts away (🧅). Each piece turns with
// the yaw on its own (S.onYaw), none inside another.
S.onYaw = []; S.spins = []; S.fastParts = [];
const AT = [0, S.HUB - 200, 0];
const onYaw = () => { const g = W.group({ at: AT }); S.onYaw.push(g); return g; };
const steel = W.paint('#5d6b78', { metallic: 0.45, rough: 0.5 });
const inner = onYaw();
inner.add(W.mesh(W.box(380, 50, 1250), steel, { at: [0, 30, -250] }));
inner.add(W.mesh(W.box(200, 200, 160), steel, { at: [0, 200, 380] }));
const shaft = W.group({ at: [0, 200, 330] });
shaft.add(W.mesh(W.cyl(45, 55, 700, 24), W.metal('#c9cdd2'), { rot: [90, 0, 0] }));
for (let k = 0; k < 6; k++) shaft.add(W.mesh(W.box(14, 14, 40), W.metal('#6a6f75'), { at: [Math.cos(k) * 52, Math.sin(k) * 52, -200] }));
inner.add(shaft);
S.spins.push(shaft);
W.add(inner, { label: 'మెయిన్ షాఫ్ట్', heat: [30, 45], layer: 2 });
const gb = onYaw();
gb.add(W.mesh(W.cyl(170, 170, 330, 32), W.paint('#3e6e8f', { metallic: 0.4, rough: 0.45 }), { at: [0, 200, -60], rot: [90, 0, 0] }));
gb.add(W.mesh(W.box(300, 260, 200), W.paint('#3e6e8f', { metallic: 0.4, rough: 0.45 }), { at: [0, 160, -300] }));
const disc = W.group({ at: [0, 140, -470] });
disc.add(W.mesh(W.cyl(85, 85, 14, 32), W.metal('#b6463a', { rough: 0.35 }), { rot: [90, 0, 0] }));
for (let k = 0; k < 8; k++) disc.add(W.mesh(W.box(12, 30, 16), W.metal('#6a6f75'), { at: [Math.cos(k * Math.PI / 4) * 60, Math.sin(k * Math.PI / 4) * 60, 0] }));
gb.add(disc);
S.fastParts.push(disc);
gb.add(W.mesh(W.box(60, 50, 40), W.paint('#e0b324'), { at: [0, 225, -470] })); // the brake calliper
W.add(gb, { label: 'గేర్‌బాక్స్', heat: [35, 78], layer: 1 });
const gen = onYaw();
gen.add(W.mesh(W.cyl(130, 130, 420, 32), W.paint('#2f6f6a', { metallic: 0.35, rough: 0.4 }), { at: [0, 140, -760], rot: [90, 0, 0] }));
gen.add(W.mesh(W.box(160, 240, 260), W.paint('#8d98a3'), { at: [110, 170, -1080] })); // the converter cabinet
W.add(gen, { label: 'జనరేటర్', heat: [35, 85], layer: 1 });
const yawM = onYaw();
yawM.add(W.mesh(W.torus(170, 22, 40, 8), W.metal('#9aa2aa'), { at: [0, 6, 0], rot: [90, 0, 0] }));
for (let k = 0; k < 4; k++) yawM.add(W.mesh(W.cyl(26, 26, 110, 12), W.paint('#3a4a5a'), { at: [Math.cos(k * 1.57 + 0.78) * 150, 70, Math.sin(k * 1.57 + 0.78) * 150] }));
W.add(yawM, { label: 'యా మోటార్లు', layer: 1 });
const cover = onYaw();
cover.add(W.mesh(W.box(440, 440, 1400, 60), S.white, { at: [0, 230, -260] }));
cover.add(W.mesh(W.box(300, 160, 40), W.paint('#c9cdd2'), { at: [0, 300, -970] })); // the cooler at the back
cover.add(W.text('JARVIS · 3 MW', { size: 50, at: [221, 250, -300], rot: [0, 90, 0], color: '#2f5f8a' }));
W.add(cover, { label: 'నాసెల్ కవర్', layer: 0, peelBy: [0, 900, 0], explode: [0, 900, 0] });
const meters = onYaw();
meters.add(W.mesh(W.cyl(5, 5, 160, 8), W.metal('#c9cdd2'), { at: [0, 530, -820] }));
S.cups = W.group({ at: [-40, 620, -820] });
for (let k = 0; k < 3; k++) S.cups.add(W.mesh(W.sphere(10, 10), W.metal('#c9cdd2'), { at: [Math.cos(k * 2.094) * 32, 0, Math.sin(k * 2.094) * 32] }));
meters.add(S.cups);
meters.add(W.mesh(W.box(4, 30, 70), W.metal('#c9cdd2'), { at: [40, 620, -850] }));
const bm = new THREE.MeshStandardMaterial({ color: 0x220000, emissive: 0xff2a1a, emissiveIntensity: 0 });
meters.add(W.mesh(W.sphere(16, 10), bm, { at: [0, 470, -600] }));
S.beacons.push(bm);
W.add(meters, { label: 'గాలి కొలిచే పరికరాలు', layer: 1 });

const S = W.store;
// the rotor: a hub with three 63 m blades; each blade turns about its own length (pitch) to take more or less wind
const AT = [0, S.HUB - 200, 0];
const hubP = W.group({ at: AT }), hubSpin = W.group({ at: [0, 200, 700] });
hubP.add(hubSpin);
hubSpin.add(W.mesh(W.sphere(190, 32), S.white, { at: [0, 0, 60], scale: [1, 1, 1.4] }));
hubSpin.add(W.mesh(W.cyl(200, 200, 160, 32), S.white, { rot: [90, 0, 0] }));
S.onYaw.push(hubP); S.spins.push(hubSpin);
W.add(hubP, { label: 'హబ్', heat: [30, 40] });
const bladesP = W.group({ at: AT }), spin = W.group({ at: [0, 200, 700] });
bladesP.add(spin);
S.pitch = [];
const bg = S.blade({ span: S.R - 200, root: 260, max: 420, tip: 70, twist: 14 });
const bladeM = W.paint('#f4f5f6', { metallic: 0.05, rough: 0.35 });
for (let i = 0; i < 3; i++) {
  const arm = W.group({ rot: [0, 0, i * 120] });
  const p = W.group({ at: [0, 200, 0] });
  p.add(new THREE.Mesh(bg, bladeM));
  p.add(W.mesh(W.box(40, 300, 30), W.paint('#c23a2e'), { at: [-4, S.R - 420, 0] })); // (red tip for aircraft)
  arm.add(p);
  spin.add(arm);
  S.pitch.push(p);
}
S.onYaw.push(bladesP); S.spins.push(spin);
W.add(bladesP, { label: 'రోటర్ బ్లేడ్లు', heat: [28, 32] });

const S = W.store;
const farm = W.group();
S.farRotors = [];
const fb = S.blade({ span: S.R - 200, root: 240, max: 380, tip: 70, twist: 12, ns: 8, nc: 6 });
for (const [x, z, yaw] of [[-18000, -16000, 0.15], [17000, -20000, -0.1]]) {
  const t = W.group({ at: [x, 0, z] });
  const prof = [[0.01, 0], [220, 0]];
  for (let i = 1; i <= 6; i++) { const k = i / 6; prof.push([220 - 90 * k, (S.HUB - 300) * k]); }
  prof.push([0.01, S.HUB - 300]);
  t.add(W.mesh(W.lathe(prof, 24), S.white));
  const y = W.group({ at: [0, S.HUB - 200, 0], rot: [0, yaw * 57.3, 0] });
  y.add(W.mesh(W.box(420, 420, 1300, 50), S.white, { at: [0, 220, -250] }));
  const r = W.group({ at: [0, 200, 700] });
  r.add(W.mesh(W.sphere(190, 16), S.white, { scale: [1, 1, 1.4] }));
  for (let i = 0; i < 3; i++) { const a = W.group({ rot: [0, 0, i * 120 + 40] }); a.add(W.mesh(fb, S.white, { at: [0, 200, 0] })); r.add(a); }
  y.add(r);
  const bm = new THREE.MeshStandardMaterial({ color: 0x220000, emissive: 0xff2a1a, emissiveIntensity: 0 });
  y.add(W.mesh(W.sphere(16, 8), bm, { at: [0, 470, -600] }));
  S.beacons.push(bm);
  t.add(y);
  farm.add(t);
  S.farRotors.push(r);
}
W.add(farm, { label: 'మిగతా గాలి మరలు', heat: [28, 32] });

const S = W.store;
// running: the power bar is the wind speed (0–20 m/s; past the limit a storm, 28 m/s). Below 3 m/s nothing; up to 12 m/s
// the power grows fast (with the wind's cube); then 3 MW and the blades pitch to spill the extra; in a storm (over 25 m/s)
// they feather and the brake stops the rotor. 🚩 "yaw": the wind turns 90° and the nacelle follows it.
const ss = W.group();
const tank = W.paint('#5f6b5e', { metallic: 0.35, rough: 0.55 }), gal = W.metal('#aab2ba', { rough: 0.45 });
ss.add(W.mesh(W.box(2600, 10, 1800), S.matte('#8b867d', 0.98), { at: [7000, 5, 9000] }));
ss.add(W.mesh(W.box(500, 360, 380), tank, { at: [6400, 200, 9000] }));
for (let k = 0; k < 3; k++) ss.add(W.mesh(W.cyl(16, 22, 180, 10), S.matte('#7a4a32', 0.4), { at: [6280 + k * 120, 470, 9000] }));
for (const z of [8300, 9700]) ss.add(W.mesh(W.box(40, 1300, 40), gal, { at: [7800, 650, z] }));
ss.add(W.mesh(W.box(40, 40, 1440), gal, { at: [7800, 1300, 9000] }));
W.add(ss, { label: 'సబ్‌స్టేషన్', heat: [28, 60] });
W.throttle({ label: 'గాలి', rise: 0.25, fall: 0.2, start: 0.5 });
const sw = W.sound({ kind: 'swoosh', label: 'రోటర్ బ్లేడ్లు', gain: 1.3 });
const gearV = W.sound({ kind: 'gear', label: 'గేర్‌బాక్స్', gain: 0.6, f0: 260 });
const genV = W.sound({ kind: 'hum', label: 'జనరేటర్', gain: 0.4, f0: 100 });
W.sound({ kind: 'air', label: 'టవర్', gain: 0.35 });
let rpm = 0, ang = 0, fast = 0, pitch = 0, yaw = 0, hudT = 0, mw = 0, farA = 0;
W.onTick((t, dt) => {
  const v = W.env.over ? 28 : 20 * Math.min(1, W.env.spool);
  const storm = v > 25, braked = W.faultOf('గేర్‌బాక్స్') === 'stop';
  const wantRpm = storm || v < 3 || braked ? 0 : Math.min(14, 6 + (v - 3) * 8 / 7);
  rpm += (wantRpm - rpm) * Math.min(1, dt * (wantRpm < rpm ? 0.35 : 0.25));
  ang += dt * rpm * Math.PI * 2 / 60;
  for (const g of S.spins) g.rotation.z = -ang;
  fast += dt * rpm * 107 * Math.PI * 2 / 60 / 12; // (the gearbox: about 107 × faster; shown slower so it can be seen)
  for (const f of S.fastParts) f.rotation.z = fast;
  const wantPitch = storm ? 88 : v > 12 ? Math.min(28, (v - 12) * 2.1) : 0;
  pitch += (wantPitch - pitch) * Math.min(1, dt * 0.8);
  for (const p of S.pitch) p.rotation.y = pitch * Math.PI / 180;
  const windDir = W.env.flag('yaw') ? Math.PI / 2 : 0;
  yaw += Math.sign(windDir - yaw) * Math.min(Math.abs(windDir - yaw), dt * 0.16);
  for (const g of S.onYaw) g.rotation.y = yaw;
  farA += dt * rpm * Math.PI * 2 / 60 * 0.95;
  S.farRotors.forEach((r, i) => { r.rotation.z = -farA - i * 0.7; });
  S.cups.rotation.y += dt * (0.5 + v * 0.6);
  const blink = Math.sin(t * 3.2) > 0.2 ? 1 : 0.06;
  for (const b of S.beacons) b.emissiveIntensity = (0.8 + 3 * W.env.dark) * blink;
  const p = storm || braked || rpm < 0.5 ? 0 : v < 3 ? 0 : v < 12 ? 3 * Math.pow((v - 3) / 9, 3) : 3;
  mw += (p * Math.min(1, rpm / 13.9 + 0.02) - mw) * Math.min(1, dt * 1.5);
  const lev = rpm / 14;
  sw.set(lev); gearV.set(lev); genV.set(mw / 3);
  if (t - hudT > 0.25) {
    hudT = t;
    W.hud({ 'గాలి వేగం': v.toFixed(1) + ' m/s (' + Math.round(v * 3.6) + ' km/h)', 'విద్యుత్': mw.toFixed(2) + ' MW', 'రోటర్': rpm.toFixed(1) + ' rpm',
      'బ్లేడ్ వాలు': Math.round(pitch) + '°', 'స్థితి': storm ? 'తుఫాను: ఆపాను' : v < 3 ? 'గాలి తక్కువ' : v > 12 ? 'ఫుల్ (3 MW)' : 'నడుస్తోంది' });
    W.report({ power: W.env.spool, wind: v, mw, rpm });
  }
});
for (const [x, y] of [[-3000, 12500], [0, 9000], [3000, 13000], [-1500, 6500], [2000, 7500], [0, 15500]]) {
  W.stream([[x, y, 9000], [x * 0.95, y, 2000], [x * 0.9, y, -2000], [x * 0.85, y - 200, -9000]], { kind: 'cool', count: 18, size: 260, speed: 1.4, spread: 600 });
}
W.stream([[0, 9900, -700], [0, 9000, 0], [0, 300, 0], [600, 100, 500], [3000, 40, 6000], [6400, 200, 9000], [7800, 1300, 9000]], { kind: 'power', count: 30, size: 110, speed: 1 });
W.walk({ eye: 165, speed: 380, area: [-25000, -29000, 25000, 12000],
  solid: [[-300, -300, 300, 300], [-18300, -16300, -17700, -15700], [16700, -20300, 17300, -19700]],
  spots: [
    { name: 'టవర్ కింద', at: [900, 0, 1700], look: [0, 6000, 0] },
    { name: 'నాసెల్ పైన', at: [60, S.HUB + 250, -350], look: [0, S.HUB + 60, 3000] },
    { name: 'పొలంలో', at: [6000, 0, 11000], look: [0, 7000, 0] },
    { name: 'సబ్‌స్టేషన్', at: [5200, 0, 10600], look: [6800, 400, 9000] },
  ] });

గేర్‌బాక్స్.code:
// Inside the gearbox, its case off: the blades turn the big input shaft slowly (about 14 a minute). Its carrier swings
// three planet gears round a small sun gear inside a fixed ring: the sun turns 5 times faster. On the sun's shaft a big gear
// drives a small pinion 4 times faster again, and that turns the generator. (Real ones have three stages: about 100 × faster.)
const steel = W.metal('#b8bec5', { rough: 0.3 }), dark = W.metal('#6f767e', { rough: 0.4 }), gold = W.metal('#c9a24a', { rough: 0.32 });
const inp = W.group();
inp.add(W.mesh(W.cyl(10, 10, 90, 32), steel, { at: [0, 92, 0] }));
const carrier = W.group({ at: [0, 44, 0] });
carrier.add(W.mesh(W.cyl(38, 38, 6, 48), dark));
inp.add(carrier);
W.add(inp, { label: 'ఇన్‌పుట్ షాఫ్ట్' });
const ring = W.group();
ring.add(W.mesh(W.ring(52, 62, 12, 64), dark, { at: [0, 30, 0] }));
for (let i = 0; i < 48; i++) { const a = (i / 48) * Math.PI * 2; ring.add(W.mesh(W.box(3, 12, 4), dark, { at: [Math.cos(a) * 51, 30, Math.sin(a) * 51], rot: [0, -a * 57.3, 0] })); }
W.add(ring, { label: 'రింగ్ గేర్' });
const planets = W.group(), pl = [];
for (let i = 0; i < 3; i++) {
  const a = (i / 3) * Math.PI * 2;
  const p = W.group({ at: [Math.cos(a) * 32, 30, Math.sin(a) * 32] });
  p.add(W.mesh(W.gear({ teeth: 18, r: 18.5, depth: 10, hole: 4 }), gold));
  p.add(W.mesh(W.cyl(4, 4, 18, 12), steel, { at: [0, 6, 0] }));
  planets.add(p); pl.push(p);
}
W.add(planets, { label: 'ప్లానెటరీ గేర్లు' });
const sun = W.group();
sun.add(W.mesh(W.gear({ teeth: 12, r: 13.5, depth: 10, hole: 0 }), steel, { at: [0, 30, 0] }));
sun.add(W.mesh(W.cyl(6, 6, 40, 16), steel, { at: [0, 12, 0] }));
const big = W.group();
big.add(W.mesh(W.gear({ teeth: 60, r: 48, depth: 8, hole: 6 }), gold, { at: [0, -4, 0] }));
W.add(sun, { label: 'సన్ గేర్' });
W.add(big, { label: 'పెద్ద గేర్' });
